MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image) {
  ExceptionInfo *exception;
  FILE *file;
  MagickBooleanType status;
  size_t number_colors;
  register ssize_t i;

  MagickAssert(image_info != (const ImageInfo *) NULL);
  MagickAssert(image != (Image *) NULL);

  if ((image->columns == 0) || (image->rows == 0))
    return MagickFalse;

  image->depth = 8;

  status = SetImageExtent(image, image->columns, image->rows);
  if (status == MagickFalse)
    return status;

  file = fopen(image->filename, "wb");
  if (file == (FILE *) NULL) {
    ThrowFileException(&image->exception, FileOpenError,
                       image->filename, "wb");
    return MagickFalse;
  }

  image->colorspace = sRGBColorspace;
  (void) SyncImagePixels(image);

  number_colors = 256;
  if (image->colors > number_colors)
    number_colors = image->colors;

  for (i = 0; i < (ssize_t) number_colors; i++) {
    MagickRealType red, green, blue;
    register PixelTrait traits;

    red = (MagickRealType) ScaleQuantumToChar(image->colormap[i].red);
    green = (MagickRealType) ScaleQuantumToChar(image->colormap[i].green);
    blue = (MagickRealType) ScaleQuantumToChar(image->colormap[i].blue);

    traits = GetPixelTraits(image, i);
    if ((traits & RedPixelTrait) != 0)
      red = image->colormap[i].red_trait;
    if ((traits & GreenPixelTrait) != 0)
      green = image->colormap[i].green_trait;
    if ((traits & BluePixelTrait) != 0)
      blue = image->colormap[i].blue_trait;

    (void) fwrite(&red, sizeof(MagickRealType), 1, file);
    (void) fwrite(&green, sizeof(MagickRealType), 1, file);
    (void) fwrite(&blue, sizeof(MagickRealType), 1, file);
  }

  for (i = 0; i < (ssize_t) image->rows; i++) {
    register PixelIndex *indexes;
    register PixelTrait *traits;

    indexes = (PixelIndex *) GetIndexes(image);
    (void) fwrite(indexes, sizeof(PixelIndex), image->columns, file);
  }

  (void) fclose(file);
  return MagickTrue;
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  MagickBooleanType status;
  FILE *file;
  size_t length, y;
  Quantum *indexes;

  if ((file = fopen(image->filename, "wb")) == (FILE *) NULL)
  {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      FileOpenError, "UnableToCreate", "%s", image->filename);
    return (MagickFalse);
  }

  if (image->depth > 8)
    image->depth = 8;

  if (image->colors > 256)
  {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      ImageError, "ColorMapOverflow", "TooManyColors");
    return (MagickFalse);
  }

  if (AllocateImageColormap(image, image->colors) == MagickFalse)
  {
    (void) fclose(file);
    return (MagickFalse);
  }

  (void) TransformImageColorspace(image, sRGBColorspace);

  length = image->columns * image->rows;
  indexes = (Quantum *) AcquireQuantumMemory(length, sizeof(*indexes));
  if (indexes == (Quantum *) NULL)
  {
    (void) fclose(file);
    return (MagickFalse);
  }

  for (y = 0; y < image->rows; y++)
  {
    register const PixelPacket *p;
    register ssize_t x;

    p = GetVirtualPixels(image, 0, y, image->columns, 1, &image->exception);
    for (x = 0; x < (ssize_t) image->columns; x++)
    {
      register ssize_t index;

      index = GetImageIndex(image, p);
      indexes[x] = (Quantum) index;
      p++;
    }

    (void) fwrite(indexes, sizeof(*indexes), image->columns, file);
  }

  (void) fclose(file);
  return (MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  ExceptionInfo
    *exception;

  FILE
    *file;

  MagickBooleanType
    status;

  MapInfo
    *map_info;

  register const PixelPacket
    *p;

  size_t
    count,
    number_colors;

  register ssize_t
    i;

  unsigned char
    *colormap,
    *indexes;

  assert(image_info != (ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);

  exception = image->exception;
  status = MagickTrue;
  file = (FILE *) NULL;

  if (image->colors > 256)
    (void) TransformImageColorspace(image, sRGBColorspace);

  if ((image->columns != image->rows) || (image->columns > 256))
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ImageError,
        "WriteFailed","width and height must be <= 256 and equal");
      return(MagickFalse);
    }

  if ((image->columns > 256) || (image->rows > 256))
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ImageError,
        "WriteFailed","width and height must be <= 256");
      return(MagickFalse);
    }

  map_info = AcquireImageColormap(image);
  if (map_info == (MapInfo *) NULL)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
        "MemoryAllocationFailed","Unable to allocate colormap memory for image");
      return(MagickFalse);
    }

  colormap = (unsigned char *) AcquireQuantumMemory(256, 3 * sizeof(*colormap));
  if (colormap == (unsigned char *) NULL)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
        "MemoryAllocationFailed","Unable to allocate colormap memory for image");
      map_info = RelinquishImageColormap(map_info);
      return(MagickFalse);
    }

  for (i = 0; i < (ssize_t) map_info->number_colors; i++)
  {
    colormap[i * 3] = ClampToQuantum(map_info->red[i]);
    colormap[i * 3 + 1] = ClampToQuantum(map_info->green[i]);
    colormap[i * 3 + 2] = ClampToQuantum(map_info->blue[i]);
  }

  if ((file = fopen(image->filename, "wb")) == (FILE *) NULL)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), FileError,
        "UnableToCreate","%s", image->filename);
      colormap = (unsigned char *) RelinquishMagickMemory(colormap);
      map_info = RelinquishImageColormap(map_info);
      return(MagickFalse);
    }

  (void) fwrite(colormap, 3, map_info->number_colors, file);

  indexes = (unsigned char *) AcquireQuantumMemory(image->columns * image->rows, sizeof(*indexes));
  if (indexes == (unsigned char *) NULL)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
        "MemoryAllocationFailed","Unable to allocate indexes memory for image");
      (void) fclose(file);
      colormap = (unsigned char *) RelinquishMagickMemory(colormap);
      map_info = RelinquishImageColormap(map_info);
      return(MagickFalse);
    }

  p = image->pixels;
  for (i = 0; i < (ssize_t) (image->columns * image->rows); i++)
  {
    indexes[i] = p->index;
    p++;
  }

  (void) fwrite(indexes, 1, image->columns * image->rows, file);
  (void) fclose(file);

  colormap = (unsigned char *) RelinquishMagickMemory(colormap);
  indexes = (unsigned char *) RelinquishMagickMemory(indexes);
  map_info = RelinquishImageColormap(map_info);
  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image) {
  int
    count;

  MagickBooleanType
    status;

  register const PixelPacket
    *p;

  register ssize_t
    i;

  size_t
    colormap_size,
    length;

  unsigned char
    *colormap,
    *pixels;

  FILE
    *file;

  if ((image == (Image *) NULL) || (image->pixels == (PixelPacket *) NULL))
    return(MagickFalse);

  status = OpenBlob(image_info, image, WriteBlob, &image->exception);
  if (status == MagickFalse)
    return(status);

  if (image->colors > 256)
    colormap_size = 768;
  else
    colormap_size = 256 * 3;

  colormap = (unsigned char *) AcquireQuantumMemory(colormap_size, sizeof(*colormap));
  if (colormap == (unsigned char *) NULL)
    {
      ThrowFileException(&image->exception, ResourceLimitError,"Unable to allocate colormap",image->filename);
      return(MagickFalse);
    }

  p = GetAuthenticPixels(image,0,0,image->columns,image->rows,&image->exception);
  if (p == (const PixelPacket *) NULL)
    {
      RelinquishQuantumMemory(colormap);
      return(MagickFalse);
    }

  length = image->rows * image->columns;
  pixels = (unsigned char *) AcquireQuantumMemory(length, sizeof(*pixels));
  if (pixels == (unsigned char *) NULL)
    {
      RelinquishQuantumMemory(colormap);
      ThrowFileException(&image->exception, ResourceLimitError,"Unable to allocate pixel indexes",image->filename);
      return(MagickFalse);
    }

  for (i = 0; i < (ssize_t) length; i++)
    pixels[i] = (unsigned char) (GetPixelIndex(image,p) + 0.5);

  if (colormap_size > 0)
    {
      for (i = 0; i < (ssize_t) image->colors; i++)
      {
        colormap[i * 3 + 0] = ClampToQuantum(image->colormap[i].red);
        colormap[i * 3 + 1] = ClampToQuantum(image->colormap[i].green);
        colormap[i * 3 + 2] = ClampToQuantum(image->colormap[i].blue);
      }

      count = fwrite(colormap, 1, colormap_size, image->file);
      if (count != (int) colormap_size)
        {
          RelinquishQuantumMemory(colormap);
          RelinquishQuantumMemory(pixels);
          CloseBlob(image);
          return(MagickFalse);
        }
    }

  count = fwrite(pixels, 1, length, image->file);
  if (count != (int) length)
    {
      RelinquishQuantumMemory(colormap);
      RelinquishQuantumMemory(pixels);
      CloseBlob(image);
      return(MagickFalse);
    }

  RelinquishQuantumMemory(colormap);
  RelinquishQuantumMemory(pixels);
  CloseBlob(image);

  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  MagickBooleanType success = MagickTrue;
  FILE *file = (FILE *) NULL;
  Colormap colormap;
  MagickSizeType number_pixels;
  Quantum *indexes = (Quantum *) NULL;
  int y;

  if ((file = fopen(image_info->filename, "wb")) == (FILE *) NULL)
    ThrowMagickException(&image->exception, GetMagickModule(), FileOpenError,
      "Unable to open file", "%s", image_info->filename);

  if (image->colors > 256)
    (void) SetImageColorspace(image, sRGBColorspace);

  colormap = (Colormap) AcquireColormap(image, 256, 0);
  if (colormap == (Colormap) NULL)
    ThrowMagickException(&image->exception, GetMagickModule(), ResourceLimitError,
      "Memory allocation failed", " while allocating colormap");

  for (y = 0; y < 256; y++)
  {
    fputc((unsigned char) colormap[y].red, file);
    fputc((unsigned char) colormap[y].green, file);
    fputc((unsigned char) colormap[y].blue, file);
  }

  number_pixels = image->rows * image->columns;
  indexes = (Quantum *) AcquireQuantumMemory(number_pixels, sizeof(*indexes));
  if (indexes == (Quantum *) NULL)
    ThrowMagickException(&image->exception, GetMagickModule(), ResourceLimitError,
      "Memory allocation failed", " while allocating pixel indexes");

  for (y = 0; y < (int) image->rows; y++)
    for (x = 0; x < (int) image->columns; x++)
      indexes[y * image->columns + x] = (Quantum) GetPixelIndex(image, x, y);

  fwrite(indexes, sizeof(*indexes), (size_t) number_pixels, file);

  indexes = (Quantum *) RelinquishMagickMemory(indexes);
  colormap = (Colormap) RelinquishMagickMemory(colormap);
  (void) fclose(file);

  return success;
}
